import { isUndefined } from 'lodash-es';
import { useCallback } from 'react';

import { useCanvas } from '../../../../core/components/canvas/hooks/useCanvas.js';
import { getHexagonGeometry } from '../../../functions/get-hexagon-geometry.js';

interface CanvasHexagonRendererProps {
  x: number;
  y: number;
  width: number;
  fillColor: string;
  strokeColor?: 'transparent' | string;
  radius?: number;
}

export const CanvasHexagonRenderer = (props: CanvasHexagonRendererProps) => {
  const { x, y, width, fillColor, strokeColor = fillColor, radius = 0 } = props;

  const hexGeometrics = getHexagonGeometry(x, y, width);

  const draw = useCallback(
    (ctx: CanvasRenderingContext2D) => {
      // Drawing the hexagon
      ctx.beginPath();
      for (let i = 0; i < hexGeometrics.length; i += 2) {
        const vertex = hexGeometrics[i];
        const lineBisect = hexGeometrics[i + 1];

        ctx.arcTo(vertex.x, vertex.y, lineBisect.x, lineBisect.y, radius);
      }
      ctx.closePath();

      // Styling
      if (strokeColor === 'transparent') {
        ctx.globalCompositeOperation = 'destination-out';
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
      } else if (!isUndefined(strokeColor)) {
        ctx.strokeStyle = strokeColor;
        ctx.stroke();
      }

      ctx.fillStyle = fillColor;
      ctx.fill();

      return false;
    },
    [x, y, width, fillColor, strokeColor],
  );

  useCanvas('honeycomb-hexagon', draw);

  return null;
};

CanvasHexagonRenderer['displayName'] = 'CanvasHexagonRenderer';
